using System.Data;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.SqlClient;

using Microsoft.Extensions.Configuration;

namespace LaooMemoModule.Controllers;

[ApiController,Authorize,Route("api/company/memo")]
public sealed class MemoWorkflowController(IConfiguration config):MemoControllerBase(config)
{
 [HttpPost("documents/{id:long}/submit")] public async Task<IActionResult> Submit(long id,SubmitRequest request,CancellationToken ct){if(request.RouteId<=0)return Invalid("ยังไม่ได้เลือกสายอนุมัติ","เลือกสายอนุมัติก่อนส่ง");if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005","SUBMIT",ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(ct);var memo=await Query(db,tx,"SELECT CurrentVersionID versionId FROM dbo.TDMEMemo WHERE CompanyID=@company AND MemoID=@id AND OwnerUserID=@user AND StatusCode IN(N'DRAFT',N'RETURNED',N'WITHDRAWN')",ct,("@company",company),("@id",id),("@user",user));if(memo.Count==0){await tx.RollbackAsync(ct);return Conflict(new{message="ส่ง Memo ไม่ได้",description="สถานะเอกสารไม่อนุญาตให้ส่ง"});}var version=Convert.ToInt64(memo[0]["versionId"]);var steps=await Query(db,tx,"SELECT StepOrder stepOrder,StepName name,AssigneeUserID userId FROM dbo.TDMEApprovalRouteStep WHERE CompanyID=@company AND RouteID=@route ORDER BY StepOrder",ct,("@company",company),("@route",request.RouteId));if(steps.Count==0||steps.Any(x=>Convert.ToInt64(x["userId"])==user)){await tx.RollbackAsync(ct);return Invalid("สายอนุมัติใช้ไม่ได้","ต้องมีผู้อนุมัติ และผู้สร้างห้ามอนุมัติ Memo ของตนเอง");}await Execute(db,tx,"DELETE dbo.TDMEMemoApproval WHERE CompanyID=@company AND MemoID=@id AND VersionID=@version",ct,("@company",company),("@id",id),("@version",version));foreach(var step in steps)await Execute(db,tx,"INSERT dbo.TDMEMemoApproval(CompanyID,MemoID,VersionID,StepOrder,StepName,AssigneeUserID,StatusCode) VALUES(@company,@id,@version,@order,@name,@assignee,CASE WHEN @order=1 THEN N'PENDING' ELSE N'WAITING' END)",ct,("@company",company),("@id",id),("@version",version),("@order",step["stepOrder"]),("@name",step["name"]),("@assignee",step["userId"]));await Execute(db,tx,"UPDATE dbo.TDMEMemo SET StatusCode=N'IN_APPROVAL',UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@id;UPDATE dbo.TDMEMemoVersion SET SubmittedAt=SYSUTCDATETIME(),UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND VersionID=@version",ct,("@company",company),("@id",id),("@version",version),("@user",user));await Audit(db,tx,company,id,version,"SUBMIT",null,user,ct);await tx.CommitAsync(ct);return NoContent();}
 [HttpPost("documents/{id:long}/withdraw")] public Task<IActionResult> Withdraw(long id,NoteRequest x,CancellationToken ct)=>OwnerState(id,"IN_APPROVAL","WITHDRAWN","WITHDRAW",x.Note,ct);
 [HttpPost("documents/{id:long}/cancel")] public Task<IActionResult> Cancel(long id,NoteRequest x,CancellationToken ct)=>OwnerState(id,null,"CANCELLED","CANCEL",x.Note,ct);
 [HttpGet("approvals")] public async Task<IActionResult> Approvals(CancellationToken ct){if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50006","VIEW",ct))return Forbid();return Ok(await Query(db,"SELECT a.ApprovalID id,m.MemoID memoId,COALESCE(m.MemoNo,m.TemporaryNo) memoNo,m.SubjectText subject,m.ConfidentialityCode confidentiality,a.StepOrder stepOrder,a.StepName stepName,a.StatusCode status,a.CreateDate FROM dbo.TDMEMemoApproval a JOIN dbo.TDMEMemo m ON m.CompanyID=a.CompanyID AND m.MemoID=a.MemoID WHERE a.CompanyID=@company AND a.AssigneeUserID=@user AND a.StatusCode=N'PENDING' ORDER BY a.CreateDate",ct,("@company",company),("@user",user)));}
 [HttpPost("approvals/{approvalId:long}/decision")] public async Task<IActionResult> Decision(long approvalId,DecisionRequest request,CancellationToken ct){var action=request.Action?.ToUpperInvariant();if(action is not("APPROVE" or "RETURN")||(action=="RETURN"&&Clean(request.Note) is null))return Invalid("ข้อมูลการพิจารณาไม่ครบ","เลือกอนุมัติหรือส่งกลับ และระบุเหตุผลเมื่อส่งกลับ");if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50006",action,ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(IsolationLevel.Serializable,ct);var rows=await Query(db,tx,"SELECT a.MemoID memoId,a.VersionID versionId,a.StepOrder stepOrder,m.OwnerUserID owner,m.MemoTypeID typeId,m.MemoNo memoNo,t.NumberPrefix prefix,COALESCE(s.AutoDistribute,1) autoDistribute FROM dbo.TDMEMemoApproval a JOIN dbo.TDMEMemo m ON m.CompanyID=a.CompanyID AND m.MemoID=a.MemoID JOIN dbo.TDMEType t ON t.CompanyID=m.CompanyID AND t.MemoTypeID=m.MemoTypeID LEFT JOIN dbo.TDMESystemSetting s ON s.CompanyID=m.CompanyID WHERE a.CompanyID=@company AND a.ApprovalID=@approval AND a.AssigneeUserID=@user AND a.StatusCode=N'PENDING' AND m.StatusCode=N'IN_APPROVAL'",ct,("@company",company),("@approval",approvalId),("@user",user));if(rows.Count==0){await tx.RollbackAsync(ct);return Conflict(new{message="ดำเนินการไม่ได้",description="งานนี้ถูกดำเนินการแล้วหรือไม่ได้อยู่ในสิทธิ์"});}var row=rows[0];if(Convert.ToInt64(row["owner"])==user){await tx.RollbackAsync(ct);return Forbid();}var memo=Convert.ToInt64(row["memoId"]);var version=Convert.ToInt64(row["versionId"]);var order=Convert.ToInt32(row["stepOrder"]);if(action=="RETURN"){await Execute(db,tx,"UPDATE dbo.TDMEMemoApproval SET StatusCode=N'RETURNED',DecisionBy=@user,DecisionAt=SYSUTCDATETIME(),DecisionNote=@note WHERE CompanyID=@company AND ApprovalID=@approval;UPDATE dbo.TDMEMemoApproval SET StatusCode=N'CANCELLED' WHERE CompanyID=@company AND MemoID=@memo AND VersionID=@version AND StatusCode IN(N'WAITING',N'PENDING');UPDATE dbo.TDMEMemo SET StatusCode=N'RETURNED',UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@memo",ct,("@user",user),("@note",request.Note!.Trim()),("@company",company),("@approval",approvalId),("@memo",memo),("@version",version));}else{await Execute(db,tx,"UPDATE dbo.TDMEMemoApproval SET StatusCode=N'APPROVED',DecisionBy=@user,DecisionAt=SYSUTCDATETIME(),DecisionNote=@note WHERE CompanyID=@company AND ApprovalID=@approval",ct,("@user",user),("@note",Clean(request.Note)),("@company",company),("@approval",approvalId));var next=await Scalar<long>(db,tx,"SELECT TOP(1) ApprovalID FROM dbo.TDMEMemoApproval WHERE CompanyID=@company AND MemoID=@memo AND VersionID=@version AND StepOrder>@order AND StatusCode=N'WAITING' ORDER BY StepOrder",ct,("@company",company),("@memo",memo),("@version",version),("@order",order));if(next>0)await Execute(db,tx,"UPDATE dbo.TDMEMemoApproval SET StatusCode=N'PENDING' WHERE CompanyID=@company AND ApprovalID=@next",ct,("@company",company),("@next",next));else await FinishApproval(db,tx,company,memo,version,user,row,ct);}await Audit(db,tx,company,memo,version,action,Clean(request.Note),user,ct);await tx.CommitAsync(ct);return NoContent();}
 async Task FinishApproval(SqlConnection db,SqlTransaction tx,long company,long memo,long version,long user,Dictionary<string,object?> row,CancellationToken ct){var existingNo=Clean(Convert.ToString(row["memoNo"]));var year=DateTime.Now.Year;if(existingNo is null)await Execute(db,tx,"MERGE dbo.TDMENumberSequence WITH(HOLDLOCK) t USING(SELECT @company CompanyID,@type MemoTypeID,@year SequenceYear) s ON t.CompanyID=s.CompanyID AND t.MemoTypeID=s.MemoTypeID AND t.SequenceYear=s.SequenceYear WHEN MATCHED THEN UPDATE SET LastNumber=LastNumber+1,UpdateDate=SYSUTCDATETIME() WHEN NOT MATCHED THEN INSERT(CompanyID,MemoTypeID,SequenceYear,LastNumber) VALUES(@company,@type,@year,1);",ct,("@company",company),("@type",row["typeId"]),("@year",year));var seq=await Scalar<int>(db,tx,"SELECT LastNumber FROM dbo.TDMENumberSequence WHERE CompanyID=@company AND MemoTypeID=@type AND SequenceYear=@year",ct,("@company",company),("@type",row["typeId"]),("@year",year));var no=existingNo??$"{row["prefix"]}-{year}-{seq:00000}";var auto=Convert.ToBoolean(row["autoDistribute"]);await Execute(db,tx,"UPDATE dbo.TDMEMemo SET MemoNo=@no,StatusCode=@status,ApprovedAt=SYSUTCDATETIME(),DistributedAt=CASE WHEN @auto=1 THEN SYSUTCDATETIME() ELSE NULL END,UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@memo;UPDATE dbo.TDMEMemoVersion SET IsLocked=1,UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND VersionID=@version",ct,("@no",no),("@status",auto?"DISTRIBUTED":"APPROVED"),("@auto",auto),("@user",user),("@company",company),("@memo",memo),("@version",version));}
 async Task<IActionResult> OwnerState(long id,string? from,string to,string action,string? note,CancellationToken ct){if(Clean(note) is null)return Invalid("กรุณาระบุเหตุผล","การดำเนินการนี้ต้องมีเหตุผล");if(!Scope(out var company,out var user))return Forbid();await using var db=await Open(ct);if(!await Can(db,"50005",action,ct))return Forbid();await using var tx=(SqlTransaction)await db.BeginTransactionAsync(ct);var where=from is null?"StatusCode NOT IN(N'CANCELLED',N'DISTRIBUTED')":"StatusCode=@from";var rows=await Query(db,tx,$"SELECT CurrentVersionID versionId FROM dbo.TDMEMemo WHERE CompanyID=@company AND MemoID=@id AND OwnerUserID=@user AND {where}",ct,("@company",company),("@id",id),("@user",user),("@from",from));if(rows.Count==0){await tx.RollbackAsync(ct);return Conflict(new{message="ดำเนินการไม่ได้",description="สถานะเอกสารไม่ถูกต้อง"});}var version=Convert.ToInt64(rows[0]["versionId"]);await Execute(db,tx,"UPDATE dbo.TDMEMemo SET StatusCode=@to,CancelReason=CASE WHEN @to=N'CANCELLED' THEN @note ELSE CancelReason END,UpdateBy=@user,UpdateDate=SYSUTCDATETIME() WHERE CompanyID=@company AND MemoID=@id;UPDATE dbo.TDMEMemoApproval SET StatusCode=N'CANCELLED' WHERE CompanyID=@company AND MemoID=@id AND StatusCode IN(N'WAITING',N'PENDING')",ct,("@to",to),("@note",note!.Trim()),("@user",user),("@company",company),("@id",id));await Audit(db,tx,company,id,version,action,note,user,ct);await tx.CommitAsync(ct);return NoContent();}
}
